/*!
 * Minimal inline-Markdown renderer.
 *
 * The spec asks for a vendored marked.min.js (MIT) purely so the UI can call
 * `marked.parseInline` on outline node text. Vendoring the full library for one
 * function would add an offline build step, so this file exposes the same entry
 * point with the inline subset the UI actually uses: escaping, code spans, bold,
 * italics, strikethrough and links. Drop in the real marked.min.js and the UI
 * keeps working unchanged.
 */
(function (global) {
  "use strict";

  var MARK = "\u0001";

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function parseInline(src) {
    if (src === null || src === undefined) return "";
    var out = escapeHtml(src);
    var codes = [];
    out = out.replace(/`+([^`]+)`+/g, function (_, code) {
      codes.push(code);
      return MARK + (codes.length - 1) + MARK;
    });
    out = out.replace(/!\[([^\]]*)\]\(([^)\s]+)[^)]*\)/g, "$1");
    out = out.replace(/\[([^\]]*)\]\(([^)\s]+)[^)]*\)/g, function (_, text, href) {
      return '<a href="' + href + '" target="_blank" rel="noreferrer">' + text + "</a>";
    });
    out = out.replace(/(\*\*|__)([\s\S]+?)\1/g, "<strong>$2</strong>");
    out = out.replace(/(?<![\w*_])([*_])(?!\s)([\s\S]+?)(?<!\s)\1(?![\w*_])/g, "<em>$2</em>");
    out = out.replace(/~~([\s\S]+?)~~/g, "<del>$1</del>");
    out = out.replace(new RegExp(MARK + "(\\d+)" + MARK, "g"), function (_, i) {
      return "<code>" + codes[Number(i)] + "</code>";
    });
    return out;
  }

  global.marked = { parseInline: parseInline, parse: parseInline, escapeHtml: escapeHtml };
})(typeof window !== "undefined" ? window : this);
